findings.suggestion:
/** The fields of the prior review record a round carries its open importants from; older records may hold null, and records before schema 7 carry no description. */
export const priorReviewSchema = z.object({
  findings: z.array(findingSchema).nullable(),
  prior_importants: z.array(priorImportantSchema.extend({ description: z.string().default("") })).nullable(),
});
